test('mergeCustomers merges two customers', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.customers.length, customers.length - 1);
  assert.ok(!result.value.customers.find((c) => c.id === 'C-001'));
  assert.ok(result.value.customers.find((c) => c.id === 'C-002'));
});

test('mergeCustomers transfers invoices', () => {
  const customers = listCustomers();
  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(invoice1, []).value;

  const invoice2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;
  const issued2 = issueInvoice(invoice2, ['INV-2026-0001']).value;

  const invoices = [issued1, issued2];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 2);
  assert.ok(!result.value.invoices.find((inv) => inv.customerId === 'C-001'));
  assert.equal(result.value.invoices.filter((inv) => inv.customerId === 'C-002').length, 2);
});

test('mergeCustomers fails if fromId does not exist', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-999', 'C-002');

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('mergeCustomers fails if intoId does not exist', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-999');

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('mergeCustomers fails if both ids are the same', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-001');

  assert.deepEqual(result, { ok: false, error: 'SAME_CUSTOMER' });
});

test('mergeCustomers normalizes customer ids', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, ' c-001 ', 'c-002');

  assert.equal(result.ok, true);
  assert.ok(!result.value.customers.find((c) => c.id === 'C-001'));
});

test('mergeCustomers does not mutate input arrays', () => {
  const customers = listCustomers();
  const originalLength = customers.length;
  const invoices = [];

  mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(customers.length, originalLength);
  assert.ok(customers.find((c) => c.id === 'C-001'));
});

test('mergeCustomers transfers multiple invoices from same customer', () => {
  const customers = listCustomers();
  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(invoice1, []).value;

  const invoice2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;
  const issued2 = issueInvoice(invoice2, ['INV-2026-0001']).value;

  const invoices = [issued1, issued2];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 2);
  assert.equal(result.value.invoices.filter((inv) => inv.customerId === 'C-002').length, 2);
});

test('mergeCustomers does not affect other customers invoices', () => {
  const customers = listCustomers();
  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(invoice1, []).value;

  const invoice2 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;
  const issued2 = issueInvoice(invoice2, ['INV-2026-0001']).value;

  const invoices = [issued1, issued2];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.filter((inv) => inv.customerId === 'C-002').length, 1);
  assert.equal(result.value.invoices.filter((inv) => inv.customerId === 'C-003').length, 1);
});

test('mergeCustomers works with draft invoices', () => {
  const customers = listCustomers();
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const invoices = [draft];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].customerId, 'C-002');
  assert.equal(result.value.invoices[0].status, 'draft');
});

test('mergeCustomers respects customer id case after normalization', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'c-001', 'C-002');

  assert.equal(result.ok, true);
  // The resulting customers should have C-002 in uppercase
  assert.ok(result.value.customers.find((c) => c.id === 'C-002'));
});

